// export default DaseboardCheckPage;
import {
  Avatar,
  Grid,
  Stack,
  Typography,
  Box,
  Button,
  Divider,
  IconButton,
  Card,
  CardContent,
} from "@mui/material";
import DasBoardCheck from "../../../components/admin/daseboardCheck/DasBoardChaeck";
import { genrateUrl } from "../../../utils/genrateUrl";
import ProfileModal from "./ProfileModal";
import { useState, useEffect, useRef } from "react";
import useWalletReport from "../../../hooks/useWalletReport";
import { useNavigate } from "react-router-dom";
import Transactions from "./Transactions";
import ChevronLeftIcon from "@mui/icons-material/ChevronLeft";
import ChevronRightIcon from "@mui/icons-material/ChevronRight";
import VisibilityIcon from "@mui/icons-material/Visibility";
import VisibilityOffIcon from "@mui/icons-material/VisibilityOff";
import SupportAgentIcon from "@mui/icons-material/SupportAgent";
import ReceiptLongIcon from "@mui/icons-material/ReceiptLong";
import PhoneIcon from "@mui/icons-material/Phone";
import MailOutlineIcon from "@mui/icons-material/MailOutline";
import VerifiedIcon from "@mui/icons-material/Verified";
import MenuBookOutlinedIcon from "@mui/icons-material/MenuBookOutlined";
import UserManualModal from "../../../common/userManualModal/UserManualModal";

/* ------------------------------------------------------------------ */
/*  Design tokens — pulled straight from the dashboard's own palette  */
/*  (the blue used on the active "ALL" pill / "MOST USED" chips, and  */
/*  the navy used in "Good Afternoon") so the rail reads as one       */
/*  product instead of a separate theme bolted on the side.           */
/*  No external font is loaded here on purpose — it inherits the      */
/*  app's default typeface, which is what already renders ₹ correctly */
/*  everywhere else in the product.                                    */
/* ------------------------------------------------------------------ */
const PB = {
  ink: "#132A46",
  inkSoft: "rgba(19,42,70,0.58)",
  paper: "#FFFFFF",
  blue: "#1656D8",
  blueDeep: "#0E3FA6",
  blueSoft: "rgba(22,86,216,0.08)",
  blueSoftBorder: "rgba(22,86,216,0.16)",
  credit: "#1E8E3E",
  debit: "#D32F2F",
  rule: "rgba(19,42,70,0.10)",
};

/* Auto-close delay for the desktop sidebar rail. */
const SIDEBAR_AUTO_CLOSE_MS = 5000;

/* ------------------------------------------------------------------ */
/*  Small "Verified" tag, styled like the dashboard's own status       */
/*  chips (MOST USED / FAST) rather than a one-off decoration.        */
/* ------------------------------------------------------------------ */
function VerifiedTag() {
  return (
    <Stack
      direction="row"
      alignItems="center"
      spacing={0.4}
      sx={{
        flexShrink: 0,
        px: 1,
        py: 0.35,
        borderRadius: "20px",
        backgroundColor: PB.blue,
      }}
    >
      <VerifiedIcon sx={{ fontSize: 13, color: "#fff" }} />
      <Typography
        sx={{
          fontSize: 10.5,
          fontWeight: 700,
          letterSpacing: "0.04em",
          color: "#fff",
        }}
      >
        VERIFIED
      </Typography>
    </Stack>
  );
}

/* ------------------------------------------------------------------ */
/*  Profile / balance card                                             */
/* ------------------------------------------------------------------ */
function ProfileCard({
  profiledata,
  showBalance,
  setShowBalance,
  setShowModal,
  setShowManualModal,
}) {
  return (
    <Card
      sx={{
        width: "100%",
        flexShrink: 0,
        borderRadius: "18px",
        background: PB.paper,
        border: `1px solid ${PB.rule}`,
        boxShadow: "0 10px 24px rgba(19,42,70,0.10)",
        borderTop: `3px solid ${PB.blue}`,
        transition: "box-shadow 0.25s ease, transform 0.25s ease",
        "&:hover": {
          boxShadow: "0 16px 32px rgba(19,42,70,0.16)",
          transform: "translateY(-1px)",
        },
      }}
    >
      <CardContent sx={{ p: 2.5, "&:last-child": { pb: 2.5 } }}>
        <Stack direction="row" justifyContent="space-between" alignItems="center">
          <Typography
            sx={{
              fontSize: 10.5,
              fontWeight: 700,
              letterSpacing: "0.14em",
              textTransform: "uppercase",
              color: PB.blue,
            }}
          >
            Account Holder
          </Typography>
          <VerifiedTag />
        </Stack>

        <Stack direction="row" spacing={1.75} alignItems="center" sx={{ mt: 1.5 }}>
          <Avatar
            src={
              profiledata?.profile
                ? profiledata?.profile
                : `https://ui-avatars.com/api/?name=${
                    profiledata?.pan_name || profiledata?.name
                  }&background=random&color=fff&w=50`
            }
            sx={{
              width: 54,
              height: 54,
              border: `2px solid ${PB.blueSoftBorder}`,
            }}
          />
          <Box sx={{ minWidth: 0 }}>
            <Typography
              sx={{
                fontWeight: 700,
                fontSize: "18px",
                color: PB.ink,
                whiteSpace: "nowrap",
                overflow: "hidden",
                textOverflow: "ellipsis",
              }}
            >
              {profiledata?.name || "—"}
            </Typography>
            <Typography
              sx={{
                fontSize: 12,
                color: PB.inkSoft,
              }}
            >
              ID · {profiledata?.pan_name || "—"}
            </Typography>
          </Box>
        </Stack>

        <Divider sx={{ my: 1.75, borderColor: PB.rule }} />

        <Stack direction="row" justifyContent="space-between" alignItems="center">
          <Box>
            <Typography
              sx={{
                fontSize: 10.5,
                fontWeight: 700,
                letterSpacing: "0.1em",
                textTransform: "uppercase",
                color: PB.inkSoft,
                mb: 0.25,
              }}
            >
              Available Balance
            </Typography>
            <Typography
              component="span"
              sx={{ fontSize: 22, fontWeight: 700, color: PB.ink }}
            >
              ₹
              <Typography
                component="span"
                sx={{
                  fontSize: 22,
                  fontWeight: 700,
                  color: PB.ink,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                {showBalance ? profiledata?.main_wallet || 0 : "••••••"}
              </Typography>
            </Typography>
          </Box>
          <IconButton
            size="small"
            onClick={() => setShowBalance((v) => !v)}
            sx={{
              width: 34,
              height: 34,
              border: `1px solid ${PB.rule}`,
              color: PB.blue,
              "&:hover": { backgroundColor: PB.blueSoft },
            }}
          >
            {showBalance ? (
              <VisibilityOffIcon sx={{ fontSize: 17 }} />
            ) : (
              <VisibilityIcon sx={{ fontSize: 17 }} />
            )}
          </IconButton>
        </Stack>

        <Button
          variant="contained"
          fullWidth
          onClick={() => setShowModal(true)}
          sx={{
            mt: 2,
            borderRadius: "10px",
            backgroundColor: PB.blue,
            color: "#fff",
            textTransform: "none",
            fontWeight: 700,
            fontSize: "14px",
            py: 0.9,
            boxShadow: "none",
            "&:hover": { backgroundColor: PB.blueDeep, boxShadow: "none" },
          }}
        >
          View Profile
        </Button>

        <Button
          variant="outlined"
          fullWidth
          onClick={() => setShowManualModal(true)}
          startIcon={<MenuBookOutlinedIcon sx={{ fontSize: 18 }} />}
          sx={{
            mt: 1.25,
            borderRadius: "10px",
            borderColor: PB.blueSoftBorder,
            backgroundColor: PB.blueSoft,
            color: PB.blue,
            textTransform: "none",
            fontWeight: 700,
            fontSize: "13.5px",
            py: 0.85,
            boxShadow: "none",
            transition: "all 0.2s ease",
            "&:hover": {
              backgroundColor: "rgba(22,86,216,0.15)",
              borderColor: PB.blue,
              boxShadow: "none",
            },
          }}
        >
          User Manual Guide
        </Button>
      </CardContent>
    </Card>
  );
}

/* ------------------------------------------------------------------ */
/*  Help center card                                                   */
/* ------------------------------------------------------------------ */
function HelpCenterCard() {
  const rows = [
    { icon: <PhoneIcon sx={{ fontSize: 17 }} />, label: "+91 1242262222" },
    { icon: <MailOutlineIcon sx={{ fontSize: 17 }} />, label: "support@bankmudraa.com" },
  ];

  return (
    <Card
      sx={{
        width: "100%",
        flexShrink: 0,
        borderRadius: "18px",
        background: PB.paper,
        border: `1px solid ${PB.rule}`,
        boxShadow: "0 10px 24px rgba(19,42,70,0.10)",
        transition: "box-shadow 0.25s ease, transform 0.25s ease",
        "&:hover": {
          boxShadow: "0 16px 32px rgba(19,42,70,0.16)",
          transform: "translateY(-1px)",
        },
      }}
    >
      <CardContent sx={{ p: 2.25, "&:last-child": { pb: 2.25 } }}>
        <Stack direction="row" spacing={1.25} alignItems="center" mb={1.5}>
          <Box
            sx={{
              width: 32,
              height: 32,
              borderRadius: "9px",
              background: `linear-gradient(135deg, ${PB.blue} 0%, ${PB.blueDeep} 100%)`,
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
            }}
          >
            <SupportAgentIcon sx={{ color: "#fff", fontSize: 18 }} />
          </Box>
          <Typography sx={{ fontWeight: 700, fontSize: "15px", color: PB.ink }}>
            Help Desk
          </Typography>
        </Stack>

        <Stack spacing={1}>
          {rows.map((r, i) => (
            <Box
              key={i}
              sx={{
                display: "flex",
                alignItems: "center",
                gap: 1.1,
                p: 1,
                pl: 1.25,
                borderRadius: "8px",
                borderLeft: `3px solid ${PB.blue}`,
                backgroundColor: PB.blueSoft,
                transition: "background-color 0.2s ease",
                "&:hover": { backgroundColor: PB.blueSoftBorder },
              }}
            >
              <Box sx={{ color: PB.blue, display: "flex" }}>{r.icon}</Box>
              <Typography
                sx={{
                  fontSize: "13px",
                  color: PB.ink,
                  fontWeight: 600,
                  wordBreak: "break-word",
                }}
              >
                {r.label}
              </Typography>
            </Box>
          ))}
        </Stack>

        <Button
          variant="outlined"
          fullWidth
          onClick={() =>
            (window.location.href =
              "mailto:support@bankmudraa.com?subject=Support Request&body=Hello BankMudraa Support,")
          }
          sx={{
            mt: 1.5,
            color: PB.blue,
            borderColor: PB.blueSoftBorder,
            textTransform: "none",
            fontWeight: 700,
            fontSize: "13px",
            borderRadius: "9px",
            py: 0.75,
            "&:hover": { backgroundColor: PB.blueSoft, borderColor: PB.blue },
          }}
        >
          Contact Us
        </Button>
      </CardContent>
    </Card>
  );
}

/* ------------------------------------------------------------------ */
/*  Recent transactions — "ledger" card                                */
/* ------------------------------------------------------------------ */
function TransactionsCard({ data, navigate, scrollHeight }) {
  const count = Array.isArray(data) ? data.length : null;

  return (
    <Card
      sx={{
        width: "100%",
        flexShrink: 0,
        borderRadius: "18px",
        background: PB.paper,
        border: `1px solid ${PB.rule}`,
        boxShadow: "0 10px 24px rgba(19,42,70,0.10)",
        display: "flex",
        flexDirection: "column",
        transition: "box-shadow 0.25s ease, transform 0.25s ease",
        "&:hover": {
          boxShadow: "0 16px 32px rgba(19,42,70,0.16)",
          transform: "translateY(-1px)",
        },
      }}
    >
      <CardContent
        sx={{
          p: 2.25,
          "&:last-child": { pb: 2.25 },
          display: "flex",
          flexDirection: "column",
        }}
      >
        <Stack direction="row" justifyContent="space-between" alignItems="center" mb={1.25}>
          <Stack direction="row" spacing={1.25} alignItems="center">
            <Box
              sx={{
                width: 32,
                height: 32,
                borderRadius: "9px",
                background: `linear-gradient(135deg, ${PB.blue} 0%, ${PB.blueDeep} 100%)`,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <ReceiptLongIcon sx={{ color: "#fff", fontSize: 18 }} />
            </Box>
            <Typography sx={{ fontWeight: 700, fontSize: "15px", color: PB.ink }}>
              Recent Transactions
            </Typography>
          </Stack>
          {count !== null && count > 0 && (
            <Box
              sx={{
                px: 1,
                py: 0.25,
                borderRadius: "20px",
                backgroundColor: PB.blueSoft,
                fontSize: 11,
                fontWeight: 700,
                color: PB.blue,
                flexShrink: 0,
              }}
            >
              {count}
            </Box>
          )}
        </Stack>

        {/* Ledger panel — fixed height so it always scrolls in place       */}
        {/* rather than pushing the rest of the card / page taller.        */}
        <Box
          sx={{
            position: "relative",
            borderRadius: "12px",
            border: `1px solid ${PB.rule}`,
            backgroundColor: "rgba(22,86,216,0.03)",
            overflow: "hidden",
          }}
        >
          {/* faint receipt watermark, purely decorative */}
          <ReceiptLongIcon
            sx={{
              position: "absolute",
              right: -18,
              bottom: -18,
              fontSize: 130,
              color: PB.blue,
              opacity: 0.05,
              pointerEvents: "none",
            }}
          />
          <Box
            sx={{
              position: "relative",
              height: scrollHeight,
              overflowY: "auto",
              overflowX: "hidden",
              px: 1,
              py: 0.75,
              "&::-webkit-scrollbar": { width: "5px" },
              "&::-webkit-scrollbar-track": { background: "transparent" },
              "&::-webkit-scrollbar-thumb": {
                background: PB.blueSoftBorder,
                borderRadius: "4px",
              },
            }}
          >
            <Transactions data={data} />
          </Box>
        </Box>

        {/* ticket-stub perforation, tying the divider to the "receipt" idea */}
        <Box sx={{ position: "relative", my: 1.5 }}>
          <Divider sx={{ borderStyle: "dashed", borderColor: PB.rule }} />
          {[0, 1].map((side) => (
            <Box
              key={side}
              sx={{
                position: "absolute",
                [side === 0 ? "left" : "right"]: -9,
                top: "50%",
                transform: "translateY(-50%)",
                width: 16,
                height: 16,
                borderRadius: "50%",
                backgroundColor: "var(--bs-primary3)",
                border: `1px solid ${PB.rule}`,
              }}
            />
          ))}
        </Box>

        <Button
          variant="text"
          fullWidth
          onClick={() => navigate("/wallet-report")}
          sx={{
            textTransform: "none",
            fontSize: "13px",
            fontWeight: 700,
            color: PB.blue,
            flexShrink: 0,
            "&:hover": { backgroundColor: PB.blueSoft, textDecoration: "none" },
          }}
        >
          View All Transactions →
        </Button>
      </CardContent>
    </Card>
  );
}

/* ------------------------------------------------------------------ */
/*  Page                                                                */
/* ------------------------------------------------------------------ */
function DaseboardCheckPage({
  profiledata,
  walletData,
  services,
  position,
  isInstantpaypresnt,
}) {
  const navigate = useNavigate();
  const [showModal, setShowModal] = useState(false);
  const [showManualModal, setShowManualModal] = useState(false);
  const [showBalance, setShowBalance] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const autoCloseRef = useRef(null);
  const isHoveredRef = useRef(false);
  const { data } = useWalletReport();

  /* Starts (or restarts) the 5s auto-close countdown. Only ever called   */
  /* when the sidebar is open and the cursor is NOT currently over it —   */
  /* callers are responsible for checking that, so this stays a plain     */
  /* "arm the timer" primitive. */
  const armAutoClose = () => {
    clearTimeout(autoCloseRef.current);
    autoCloseRef.current = setTimeout(() => {
      setSidebarOpen(false);
    }, SIDEBAR_AUTO_CLOSE_MS);
  };

  const clearAutoClose = () => {
    clearTimeout(autoCloseRef.current);
    autoCloseRef.current = null;
  };

  /* Re-arm the timer any time the sidebar opens (initial mount, or the    */
  /* user re-opening it via the toggle handle) — as long as the cursor     */
  /* isn't already sitting on the rail. */
  useEffect(() => {
    if (sidebarOpen && !isHoveredRef.current) {
      armAutoClose();
    } else {
      clearAutoClose();
    }
    return clearAutoClose;
  }, [sidebarOpen]);

  /* Cursor enters the rail: pause the countdown for as long as it's there. */
  const handleRailMouseEnter = () => {
    isHoveredRef.current = true;
    clearAutoClose();
  };

  /* Cursor leaves the rail: resume a fresh 5s countdown. */
  const handleRailMouseLeave = () => {
    isHoveredRef.current = false;
    if (sidebarOpen) {
      armAutoClose();
    }
  };

  const handleToggleSidebar = () => {
    setSidebarOpen((prev) => !prev);
  };

  return (
    <Grid
      container
      sx={{
        height: "100%",
        overflow: "auto",
        backgroundColor: "var(--bs-primary3)",
        position: "relative",
      }}
    >
      {/* Left scrollable section */}
      <Grid
        item
        xs={12}
        md={sidebarOpen ? 10.2 : 12}
        sx={{
          height: "100%",
          overflowY: "auto",
          pr: { xs: 0, md: 2 },
          scrollbarWidth: "none",
          "&::-webkit-scrollbar": { display: "none" },
          transition: "all 0.65s cubic-bezier(0.4, 0, 0.2, 1)",
        }}
      >
        <DasBoardCheck
          walletData={walletData}
          services={services}
          position={position}
          isInstantpaypresnt={isInstantpaypresnt}
        />
      </Grid>

      {/* Mobile view (xs–sm only) */}
      <Grid
        item
        xs={12}
        sx={{
          display: { xs: "flex", md: "none" },
          flexDirection: "column",
          alignItems: "center",
          gap: 2,
          mt: 2,
          px: 2,
          pb: 2,
        }}
      >
        <ProfileCard
          profiledata={profiledata}
          showBalance={showBalance}
          setShowBalance={setShowBalance}
          setShowModal={setShowModal}
          setShowManualModal={setShowManualModal}
        />
        <HelpCenterCard />
        <TransactionsCard data={data} navigate={navigate} scrollHeight="230px" />
      </Grid>

      {/* Toggle handle — desktop only */}
      <Box
        sx={{
          display: { xs: "none", md: "block" },
          position: "fixed",
          right: sidebarOpen ? "335px" : "10px",
          top: "50%",
          transform: "translateY(-50%)",
          zIndex: 1300,
          transition: "all 0.65s cubic-bezier(0.4, 0, 0.2, 1)",
        }}
      >
        <IconButton
          onClick={handleToggleSidebar}
          sx={{
            backgroundColor: PB.blue,
            color: "#fff",
            boxShadow: "0 4px 14px rgba(19,42,70,0.30)",
            width: "42px",
            height: "42px",
            "&:hover": { backgroundColor: PB.blueDeep },
            border: "2px solid #fff",
          }}
        >
          {sidebarOpen ? <ChevronRightIcon /> : <ChevronLeftIcon />}
        </IconButton>
      </Box>

      {/* Fixed right rail — desktop only */}
      <Box
        sx={{
          display: { xs: "none", md: "flex" },
          position: "fixed",
          right: sidebarOpen ? 0 : "-330px",
          top: 0,
          height: "100%",
          width: "330px",
          flexDirection: "column",
          alignItems: "center",
          gap: 2,
          overflowY: "auto",
          overflowX: "hidden",
          backgroundColor: "var(--bs-primary3)",
          borderTopLeftRadius: "28px",
          transition: "all 0.65s cubic-bezier(0.4, 0, 0.2, 1)",
          zIndex: 1200,
          pt: 2,
          pb: 2,
          px: 1.5,
          boxShadow: sidebarOpen ? "-6px 0 24px rgba(20,36,56,0.10)" : "none",
          scrollbarWidth: "thin",
          "&::-webkit-scrollbar": { width: "5px" },
          "&::-webkit-scrollbar-track": { background: "transparent" },
          "&::-webkit-scrollbar-thumb": { background: PB.rule, borderRadius: "4px" },
        }}
        onMouseEnter={handleRailMouseEnter}
        onMouseLeave={handleRailMouseLeave}
      >
        <ProfileCard
          profiledata={profiledata}
          showBalance={showBalance}
          setShowBalance={setShowBalance}
          setShowModal={setShowModal}
          setShowManualModal={setShowManualModal}
        />
        <HelpCenterCard />
        <TransactionsCard data={data} navigate={navigate} scrollHeight="280px" />
      </Box>

      <ProfileModal
        show={showModal}
        handleClose={() => setShowModal(false)}
        profiledata={profiledata}
      />

      <UserManualModal
        open={showManualModal}
        onClose={() => setShowManualModal(false)}
      />
    </Grid>
  );
}

export default DaseboardCheckPage;