import React, { useState, useRef } from "react";
import { Modal, Button } from "react-bootstrap";
import {
  Box,
  Typography,
  Stack,
  Avatar,
  Divider,
  Grid,
  Paper,
  Menu,
  MenuItem,
  ListItemIcon,
  ListItemText,
} from "@mui/material";
import AccountBalanceWalletIcon from "@mui/icons-material/AccountBalanceWallet";
import SavingsIcon from "@mui/icons-material/Savings";
import RedeemIcon from "@mui/icons-material/Redeem";
import LockIcon from "@mui/icons-material/Lock";
import PersonIcon from "@mui/icons-material/Person";
import StorefrontIcon from "@mui/icons-material/Storefront";
import AccountBalanceIcon from "@mui/icons-material/AccountBalance";
import VerifiedIcon from "@mui/icons-material/Verified";
import CameraAltIcon from "@mui/icons-material/CameraAlt";
import PhotoLibraryIcon from "@mui/icons-material/PhotoLibrary";
import PhotoCameraIcon from "@mui/icons-material/PhotoCamera";
import DeleteOutlineIcon from "@mui/icons-material/DeleteOutline";
import { genrateUrl } from "../../../utils/genrateUrl";

/* ------------------------------------------------------------------ */
/*  Same token set as the dashboard sidebar, so the modal reads as    */
/*  one product rather than a separately-themed popup.                */
/* ------------------------------------------------------------------ */
const PB = {
  ink: "#132A46",
  inkSoft: "rgba(19,42,70,0.58)",
  paper: "#FFFFFF",
  blue: "#1656D8",
  blueDeep: "#0E3FA6",
  blueSoft: "rgba(22,86,216,0.06)",
  blueSoftBorder: "rgba(22,86,216,0.16)",
  credit: "#1E8E3E",
  amber: "#B45309",
  danger: "#C0392B",
  rule: "rgba(19,42,70,0.10)",
  bg: "#F4F7FC",
};

/* Small label/value tile, reused across every section instead of      */
/* repeating the same Paper markup six times over.                     */
function InfoTile({ label, value, xs = 12, sm = 6 }) {
  return (
    <Grid item xs={xs} sm={sm}>
      <Paper
        elevation={0}
        sx={{
          p: 1.2,
          borderRadius: "10px",
          background: PB.blueSoft,
          border: `1px solid ${PB.blueSoftBorder}`,
        }}
      >
        <Typography
          sx={{
            fontSize: "10.5px",
            fontWeight: 700,
            letterSpacing: "0.04em",
            textTransform: "uppercase",
            color: PB.inkSoft,
            mb: 0.25,
          }}
        >
          {label}
        </Typography>
        <Typography sx={{ fontSize: "13.5px", fontWeight: 600, color: PB.ink }}>
          {value || "—"}
        </Typography>
      </Paper>
    </Grid>
  );
}

/* Section shell with a small gradient icon badge + heading, matching  */
/* the sidebar card headers (Help Desk / Recent Transactions).         */
function SectionCard({ icon, title, children }) {
  return (
    <Paper
      elevation={0}
      sx={{
        p: 2,
        mb: 2,
        borderRadius: "16px",
        background: PB.paper,
        border: `1px solid ${PB.rule}`,
        boxShadow: "0 6px 16px rgba(19,42,70,0.06)",
      }}
    >
      <Stack direction="row" spacing={1.1} alignItems="center" mb={1.5}>
        <Box
          sx={{
            width: 28,
            height: 28,
            borderRadius: "8px",
            background: `linear-gradient(135deg, ${PB.blue} 0%, ${PB.blueDeep} 100%)`,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
          }}
        >
          {icon}
        </Box>
        <Typography sx={{ fontSize: "13.5px", fontWeight: 700, color: PB.ink }}>
          {title}
        </Typography>
      </Stack>
      {children}
    </Paper>
  );
}

/* Wallet stat card — one accent color per wallet so Main / AEPS /     */
/* Cashback / Locking are distinguishable at a glance.                 */
function WalletStat({ icon, label, value, color }) {
  return (
    <Paper
      elevation={0}
      sx={{
        p: 1.5,
        flex: "1 1 120px",
        minWidth: 110,
        textAlign: "center",
        borderRadius: "14px",
        background: PB.paper,
        border: `1px solid ${PB.rule}`,
        boxShadow: "0 6px 14px rgba(19,42,70,0.06)",
      }}
    >
      <Box
        sx={{
          width: 30,
          height: 30,
          mx: "auto",
          mb: 0.75,
          borderRadius: "50%",
          backgroundColor: `${color}1A`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {React.cloneElement(icon, { sx: { fontSize: 16, color } })}
      </Box>
      <Typography
        sx={{
          fontSize: "10px",
          fontWeight: 700,
          letterSpacing: "0.05em",
          textTransform: "uppercase",
          color: PB.inkSoft,
          mb: 0.25,
        }}
      >
        {label}
      </Typography>
      <Typography sx={{ fontSize: "15px", fontWeight: 700, color: PB.ink }}>
        ₹{value || 0}
      </Typography>
    </Paper>
  );
}

/**
 * Avatar + camera badge + menu (gallery / camera / remove).
 * Kept as its own component since it owns file inputs, a menu anchor,
 * and the "does a photo currently exist" branching logic.
 *
 * Props:
 *  - src: current photo url (or null)
 *  - name: fallback initial-avatar name
 *  - onPhotoChange(file | null): fires with a File on add, or null on remove
 */
function EditableAvatar({ src, name, onPhotoChange }) {
  const [anchorEl, setAnchorEl] = useState(null);
  const [previewSrc, setPreviewSrc] = useState(null);
  const galleryInputRef = useRef(null);
  const cameraInputRef = useRef(null);

  const menuOpen = Boolean(anchorEl);
  const currentSrc =
    previewSrc ||
    src ||
    `https://ui-avatars.com/api/?name=${name || "U"}&background=random&color=fff&w=50`;
  const hasPhoto = Boolean(previewSrc || src);

  const openMenu = (e) => setAnchorEl(e.currentTarget);
  const closeMenu = () => setAnchorEl(null);

  const handleFilePicked = (e) => {
    const file = e.target.files?.[0];
    closeMenu();
    if (!file) return;

    // Local preview so the icon updates immediately; parent still gets
    // the raw file to actually upload.
    const objectUrl = URL.createObjectURL(file);
    setPreviewSrc(objectUrl);
    onPhotoChange?.(file);

    // reset so picking the same file twice still fires onChange
    e.target.value = "";
  };

  
  

  return (
    <Box sx={{ position: "relative", width: 88, height: 88 }}>
      <Avatar
        src={currentSrc}
        sx={{
          width: 88,
          height: 88,
          border: `3px solid ${PB.paper}`,
          boxShadow: `0 0 0 3px ${PB.blueSoftBorder}, 0 8px 20px rgba(19,42,70,0.16)`,
        }}
      />

      {/* Camera badge — opens the edit menu */}
      <Box
        component="button"
        type="button"
        onClick={openMenu}
        aria-label="Edit profile photo"
        sx={{
          position: "absolute",
          right: -2,
          bottom: -2,
          width: 30,
          height: 30,
          borderRadius: "50%",
          border: `2px solid ${PB.paper}`,
          background: `linear-gradient(135deg, ${PB.blue} 0%, ${PB.blueDeep} 100%)`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          cursor: "pointer",
          boxShadow: "0 4px 10px rgba(19,42,70,0.22)",
          p: 0,
        }}
      >
        <CameraAltIcon sx={{ fontSize: 15, color: "#fff" }} />
      </Box>

      {/* Hidden inputs — gallery accepts any image, camera forces the device camera */}
      <input
        ref={galleryInputRef}
        type="file"
        accept="image/*"
        hidden
        onChange={handleFilePicked}
      />
      <input
        ref={cameraInputRef}
        type="file"
        accept="image/*"
        capture="user"
        hidden
        onChange={handleFilePicked}
      />

      <Menu
        anchorEl={anchorEl}
        open={menuOpen}
        onClose={closeMenu}
        anchorOrigin={{ vertical: "bottom", horizontal: "center" }}
        transformOrigin={{ vertical: "top", horizontal: "center" }}
      >
        <MenuItem onClick={() => galleryInputRef.current?.click()}>
          <ListItemIcon>
            <PhotoLibraryIcon sx={{ fontSize: 18, color: PB.blue }} />
          </ListItemIcon>
          <ListItemText primaryTypographyProps={{ fontSize: 13.5 }}>
            Choose from Gallery
          </ListItemText>
        </MenuItem>

        <MenuItem onClick={() => cameraInputRef.current?.click()}>
          <ListItemIcon>
            <PhotoCameraIcon sx={{ fontSize: 18, color: PB.blue }} />
          </ListItemIcon>
          <ListItemText primaryTypographyProps={{ fontSize: 13.5 }}>
            Take Photo
          </ListItemText>
        </MenuItem>

        
      </Menu>
    </Box>
  );
}

const ProfileModal = ({ show, handleClose, profiledata, onPhotoChange }) => {
  if (!profiledata) return null;

  const business = profiledata?.businessInfo || {};
  const bank = profiledata?.bankDetails || {};
  const userType = profiledata?.user_type_id?.user_type || "-";

  return (
    <Modal
      show={show}
      onHide={handleClose}
      centered
      size="md"
      className="custom-modal"
      backdrop="static"
    >
      <Modal.Header
        closeButton
        style={{
          backgroundColor: PB.paper,
          borderBottom: `1px solid ${PB.rule}`,
        }}
      >
        <Modal.Title style={{ color: PB.ink, fontWeight: 700 }}>
          Profile Details
        </Modal.Title>
      </Modal.Header>

      <Modal.Body
        style={{
          backgroundColor: PB.bg,
          maxHeight: "70vh",
          overflowY: "auto",
        }}
      >
        {/* Profile Header */}
        <Stack alignItems="center" spacing={1} mb={2.5}>
          <EditableAvatar
            src={profiledata?.profile}
            name={profiledata?.pan_name || profiledata?.name}
            onPhotoChange={onPhotoChange}
          />
          <Typography
            sx={{ fontWeight: 700, fontSize: "18px", textAlign: "center", color: PB.ink }}
          >
            {profiledata?.name || "—"}
          </Typography>
          <Stack
            direction="row"
            alignItems="center"
            spacing={0.5}
            sx={{
              px: 1.25,
              py: 0.4,
              borderRadius: "20px",
              backgroundColor: PB.blue,
            }}
          >
            <VerifiedIcon sx={{ fontSize: 13, color: "#fff" }} />
            <Typography sx={{ fontSize: "11px", fontWeight: 700, color: "#fff" }}>
              CODE · {profiledata?.refer_id || "N/A"}
            </Typography>
          </Stack>
        </Stack>

        {/* Wallet Summary */}
        <Stack direction="row" spacing={1.25} rowGap={1.25} justifyContent="center" mb={2.5} flexWrap="wrap">
          <WalletStat
            icon={<AccountBalanceWalletIcon />}
            label="Main"
            value={profiledata?.main_wallet}
            color={PB.blue}
          />
          <WalletStat
            icon={<SavingsIcon />}
            label="AEPS"
            value={profiledata?.aeps_wallet}
            color={PB.blueDeep}
          />
          <WalletStat
            icon={<RedeemIcon />}
            label="Cashback"
            value={profiledata?.cashback_wallet}
            color={PB.credit}
          />
          <WalletStat
            icon={<LockIcon />}
            label="Locking"
            value={profiledata?.locking_amt}
            color={PB.amber}
          />
        </Stack>

        <Divider sx={{ mb: 2.5, borderColor: PB.rule }} />

        {/* Personal Details */}
        <SectionCard
          icon={<PersonIcon sx={{ fontSize: 16, color: "#fff" }} />}
          title="Personal Information"
        >
          <Grid container spacing={1.25}>
            <InfoTile label="Email" value={profiledata?.email} />
            <InfoTile label="Mobile" value={profiledata?.mobile} />
            <InfoTile label="State" value={profiledata?.state} />
            <InfoTile label="PIN" value={profiledata?.pinCode} />
            <InfoTile label="User Type" value={userType} />
            <InfoTile label="Education" value={profiledata?.educationQualification} />
            <InfoTile label="Address" value={profiledata?.presentAddr} xs={12} sm={12} />
          </Grid>
        </SectionCard>

        {/* Business Details */}
        <SectionCard
          icon={<StorefrontIcon sx={{ fontSize: 16, color: "#fff" }} />}
          title="Business Information"
        >
          <Grid container spacing={1.25}>
            {profiledata?.isGstAvailable ? (
              <>
                <InfoTile label="GST Number" value={business?.gst_NUmber} />
                <InfoTile label="Legal Name" value={business?.legal_name_of_business} />
                <InfoTile
                  label="Business Type"
                  value={business?.constitution_of_business}
                  xs={12}
                  sm={12}
                />
              </>
            ) : (
              <InfoTile label="Shop Name" value={profiledata?.shop_name} xs={12} sm={12} />
            )}
            <InfoTile
              label="Business Address"
              value={business?.business_Address || profiledata?.business_Address}
              xs={12}
              sm={12}
            />
            <InfoTile label="Area" value={business?.business_Area || profiledata?.business_Area} />
            <InfoTile label="City" value={business?.business_city || profiledata?.business_city} />
          </Grid>
        </SectionCard>

        {/* Bank Details */}
        {bank && (
          <SectionCard
            icon={<AccountBalanceIcon sx={{ fontSize: 16, color: "#fff" }} />}
            title="Bank Details"
          >
            <Grid container spacing={1.25}>
              <InfoTile label="Bank Name" value={bank?.bank_name} />
              <InfoTile label="Account Number" value={bank?.bank_account_number} />
              <InfoTile label="IFSC Code" value={bank?.bank_ifsc} />
              <InfoTile label="Account Holder" value={bank?.bank_account_name} />
            </Grid>
          </SectionCard>
        )}
      </Modal.Body>

      <Modal.Footer style={{ backgroundColor: PB.paper, borderTop: `1px solid ${PB.rule}` }}>
        <Button
          onClick={handleClose}
          style={{
            backgroundColor: PB.blue,
            borderColor: PB.blue,
            fontWeight: 600,
            borderRadius: "8px",
            padding: "6px 18px",
          }}
        >
          Close
        </Button>
      </Modal.Footer>
    </Modal>
  );
};

export default ProfileModal;